<script setup lang="ts">
import {ref} from 'vue';import PageShell from '../../components/PageShell.vue';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {money,time,status} from '../../utils/format';const income=ref<any>({}),profile=ref<any>({}),rows=ref<any[]>([]);const {loading,error,load}=usePage(async()=>{[income.value,profile.value]=await Promise.all([request('/sitter/income'),request('/sitter/profile')]);rows.value=(await request('/sitter/settlements?size=100')).list})
</script><template><PageShell title="我的收益" active="income" :loading="loading" :error="error" @retry="load"><view class="dark-card"><text class="muted">本月收入 · 扣除平台抽成后</text><view class="amount" style="font-size:42px;margin:16px 0">{{money(income.income)}}</view><view class="row"><text>已结算 {{money(income.settled)}}</text><text>待结算 {{money(Number(income.income||0)-Number(income.settled||0))}}</text></view></view><view class="grid"><view class="tile metric"><view class="amount">{{income.orders||0}}</view><text class="muted">本月完单</text></view><view class="tile metric"><view class="amount">{{profile.rating||'—'}}</view><text class="muted">综合评分</text></view></view><view class="notice" style="margin-top:18px">当前等级 {{profile.grade_code}} · 平台抽成 {{profile.commission_rate}}%。历史订单以订单冻结比例计算。</view><view class="section">结算明细</view><view v-for="s in rows" :key="s.id" class="card"><view class="row"><text>订单 #{{s.order_id}}</text><text class="link">＋{{money(s.sitter_amount)}}</text></view><view class="row muted"><text>{{time(s.created_at)}}</text><text>{{status(s.status)}}</text></view></view><view v-if="!rows.length" class="empty">服务完成后，收益明细会显示在这里。</view></PageShell></template>
